let activityCategorySelection=null,activitySubcategorySelection=null,activityView='categories';let page=globalThis.__ROSY_PREVIEW__?'invest':'home',reportTab='cashflow',focusMonth=new Date().getMonth()+1,filter='All',planTab='recurring',wealthTab='accounts',statementAccountId=null,statementFrom='',statementTo='',editId=null,editCollection='transactions';
let transactionCache=new Map();function invalidateTransactionCache(){transactionCache.clear()}function effectiveTransactions(db,year){if(db!==state)return calculateTransactions(db,year);if(!transactionCache.has(year))transactionCache.set(year,calculateTransactions(db,year));return transactionCache.get(year)}
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatters=new Map();const format=n=>{const c=state.currency||'INR';if(!formatters.has(c))formatters.set(c,new Intl.NumberFormat('en-IN',{style:'currency',currency:c,maximumFractionDigits:0}));return formatters.get(c).format(fromPaise(n||0))};const num=n=>Number.isFinite(Number(n))?Number(n):0;const uid=()=>globalThis.crypto?.randomUUID?.()||String(Date.now())+Math.random();const now=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
