 if(collection==='trade')fields=pSelect('holdingId','Holding *',holdings,values.holdingId||holdings[0]?.[0])+pSelect('kind','Transaction type',[['BUY','Buy / SIP executed'],['SELL','Sell / Redeem'],['DIVIDEND','Dividend paid out']],values.kind||'BUY')+pField('date','Trade / allotment date',values.date||now(),'date','required')+pField('units','Units / shares (0 for dividend)',values.units??'','number','min="0" step="0.000001" required')+pField('amount','Gross transaction amount (₹)',values.amount||'','number','min="0.01" step="0.01" required')+pField('fees','Brokerage / charges (₹)',values.fees||0,'number','min="0" step="0.01" required')+pSelect('bankAccountId','Linked bank account (optional)',[['','Unlinked · no bank adjustment'],...(state.accounts||[]).filter(a=>a.type!=='Card').map(a=>[a.id,a.name])],values.bankAccountId||'',false)+pField('ref','Broker transaction reference (optional)',values.ref||'')+`<p class="p-caption">Choose a bank account only if the cash movement is NOT already recorded in Activity. Linking creates a single Transfer; leave blank to prevent double-counting.</p>`;
