function savePortfolioForm(e){e.preventDefault();const form=e.target,raw=Object.fromEntries(new FormData(form));const {collection,id}=portfolioEdit;const kindMap={holding:'portfolioHoldings',trade:'portfolioTrades',sip:'portfolioSips',snapshot:'portfolioSnapshots'};const name=kindMap[collection];if(!name)return;
 const old=(state[name]||[]).find(x=>x.id===id);const record={...old,...raw,id:id||uid()};
 try{
  if(collection==='holding'){record.price=Number(record.price);validateHolding(record,state.portfolioHoldings);}
  if(collection==='trade'){
   record.kind=record.kind.toUpperCase();for(const k of ['units','amount','fees'])record[k]=Number(record[k]);if(record.kind==='DIVIDEND')record.units=0;
   if(record.bankAccountId&&!state.accounts.some(a=>a.id===record.bankAccountId))throw Error('Choose a valid bank account.');
   validateTrade(record,state.portfolioHoldings,state.portfolioTrades);
   if(record.bankAccountId&&record.bankAccountId!==old?.bankAccountId&&!confirm('Create a linked Transfer in Activity for this investment transaction? Choose Cancel if the bank movement is already entered.'))return;
  }
  if(collection==='sip'){record.amount=Number(record.amount);record.day=Number(record.day);record.active=record.active==='true';if(!(record.amount>0)||!Number.isInteger(record.day)||record.day<1||record.day>28||!dateOK(record.start))throw Error('Enter a valid amount, day 1–28, and start date.');}
  if(collection==='snapshot'){record.value=Number(record.value);if(!dateOK(record.date)||!Number.isFinite(record.value)||record.value<0)throw Error('Enter a valid valuation date and nonnegative amount.');if(state.portfolioSnapshots.some(x=>x.id!==record.id&&x.date===record.date&&x.owner===record.owner))throw Error('A snapshot exists for this date. Edit it instead.');}
  const items=state[name]||[];if(id){const idx=items.findIndex(x=>x.id===id);if(idx<0)throw Error('Record not found.');items[idx]=record;}else items.push(record);
  if(collection==='trade')state=reconcileCash(state);
  $('#portfolioDialog').close();save();
 }catch(error){alert(error.message)}
}
function deletePortfolioEntry(){const {collection,id}=portfolioEdit,kindMap={holding:'portfolioHoldings',trade:'portfolioTrades',sip:'portfolioSips',snapshot:'portfolioSnapshots'},name=kindMap[collection];if(!name||!id)return;
 if(collection==='holding'&&(state.portfolioTrades.some(t=>t.holdingId===id)||state.portfolioSips.some(t=>t.holdingId===id)))return alert('Remove its trades and SIP plans before deleting this holding.');
 if(!confirm('Delete this portfolio record? This may change balances and portfolio returns.'))return;
 const next=state[name].filter(v=>v.id!==id);
 if(collection==='trade'){for(const t of next.filter(t=>t.holdingId===state.portfolioTrades.find(x=>x.id===id)?.holdingId))try{validateTrade(t,state.portfolioHoldings,next)}catch(error){return alert('Cannot delete this purchase while later sales depend on it. '+error.message)}}
 state[name]=next;if(collection==='trade')state=reconcileCash(state);$('#portfolioDialog').close();portfolioDetail=null;save();
}
function downloadPortfolioTemplate(){const headers='date,holding_id,kind,units,amount,fees,ref\n';const vals=(state.portfolioHoldings||[])[0];const guide=vals?`2026-01-05,${vals.id},BUY,10,2500,0,optional-reference\n`:'';downloadFile(new Blob(['\uFEFF',headers,guide],{type:'text/csv;charset=utf-8'}),'rosy-sage-v15-trade-import-template.csv')}
function exportPortfolioHoldings(){const rows=portfolioSummary(state,now(),portfolioOwner).holdings.map(h=>({owner:ownerOf(h.holding),holding_id:h.holding.id,name:h.holding.name,asset_type:h.holding.assetType,isin:h.holding.isin||'',platform:h.holding.platform||'',units:h.units,remaining_cost:rupees(h.cost),current_price:h.price,market_value:rupees(h.value),unrealized_gain:rupees(h.unrealized),realized_gain:rupees(h.realized),dividends:rupees(h.dividends),price_date:h.priceDate||''}));downloadFile(new Blob(['\uFEFF',datasetToCsv('holdings',rows)],{type:'text/csv;charset=utf-8'}),'rosy-sage-v15-holdings.csv')}
function downloadMonthlyTemplate(){
 const selected=(state.portfolioHoldings||[]).filter(h=>portfolioOwner==='all'||ownerOf(h)===portfolioOwner);
 const rows=['as_of,holding_id,units,price,market_value'];for(const h of selected){const ledger=portfolioSummary(state,now(),ownerOf(h)).holdings.find(x=>x.holding.id===h.id);if(ledger)rows.push(`${now()},${h.id},${ledger.units},${Number(h.price)||0},${rupees(ledger.value)}`)}
 downloadFile(new Blob(['\uFEFF'+rows.join('\n')+'\n'],{type:'text/csv;charset=utf-8'}),'rosy-sage-monthly-holdings-template.csv');
}
function runPortfolioAction(action,el){
 if(action==='monthly-template')downloadMonthlyTemplate();
 if(action==='monthly-import'){if(!['Cherry','Chinju'].includes(portfolioOwner))return alert('Choose Cherry or Chinju above before uploading a statement.');document.querySelector('#portfolioMonthlyCsv').click();}
 if(action==='monthly-cancel'){monthlyPending=null;render()}
 if(action==='monthly-confirm'){
  if(!monthlyPending||monthlyPending.errors.length||monthlyPending.warnings.length||!monthlyPending.entries.length)return;
  const p=monthlyPending;const already=(state.portfolioSnapshots||[]).find(x=>x.owner===p.owner&&x.date===p.date);
  if(!confirm(`Apply ${p.owner} statement dated ${p.date} for ${p.entries.length} securities? This will update stored prices and valuation snapshot, but not quantities, trades or bank cash.`))return;
  for(const entry of p.entries){const h=state.portfolioHoldings.find(x=>x.id===entry.holdingId);if(h && (!h.priceDate||h.priceDate<=p.date)){h.price=entry.price;h.priceDate=p.date;}}
  if(already){already.value=p.total;already.source='monthly-csv'}else state.portfolioSnapshots.push({id:uid(),owner:p.owner,date:p.date,value:p.total,source:'monthly-csv'});
  monthlyPending=null;save();alert('Monthly valuation imported. Trades, SIPs and cash balances were not changed.');
 }

 if(action==='opening-import'){if(!['Cherry','Chinju'].includes(portfolioOwner))return alert('Choose Cherry or Chinju before importing opening holdings.');document.querySelector('#portfolioOpeningCsv').click();}
 if(action==='opening-cancel'){openingPending=null;render();}
 if(action==='opening-confirm'){
  const p=openingPending;
  if(!p||p.errors.length||!p.holdings.length||p.owner!==portfolioOwner)return;
  if(state.portfolioHoldings.some(h=>ownerOf(h)===p.owner)||state.portfolioSnapshots.some(s=>s.owner===p.owner&&s.date===p.date))return alert('The opening portfolio already exists. Import cancelled to prevent duplicates.');
  if(!confirm(`Load ${p.holdings.length} ${p.owner} holdings dated ${p.date} worth ${portfmt(money(p.reported))}? No bank/card cash balances will change.`))return;
  state.portfolioHoldings.push(...p.holdings);state.portfolioTrades.push(...p.trades);
  state.portfolioSnapshots.push({id:uid(),owner:p.owner,date:p.date,value:p.reported,source:'zerodha-opening-csv'});
  openingPending=null;save();alert(`${p.owner} opening portfolio imported. Verify dashboard total and synchronize your cloud.`);
 }
 if(action==='new-holding')openPortfolioForm('holding');
 if(action==='new-trade')openPortfolioForm('trade',null,{holdingId:el.dataset.pholding||portfolioDetail||undefined});
 if(action==='new-sip')openPortfolioForm('sip');
 if(action==='new-snapshot')openPortfolioForm('snapshot');
 if(action==='csv-template')downloadPortfolioTemplate();
 if(action==='export-holdings')exportPortfolioHoldings();
 if(action==='csv-import'){if(!['Cherry','Chinju'].includes(portfolioOwner))return alert('Choose Cherry or Chinju before uploading the Zerodha tradebook.');$('#portfolioCsv').click();}
 if(action==='cancel-import'){csvPending=null;render()}
 if(action==='confirm-import'){if(!csvPending||csvPending.errors.length||!csvPending.parsed.length)return;const accepted=[];for(const x of csvPending.parsed){if(!duplicateTrade(x,[...state.portfolioTrades,...accepted]))accepted.push(x)}state.portfolioTrades.push(...accepted);csvPending=null;save();alert(`Imported ${accepted.length} records. Bank balances unchanged; link cash movements after reconciliation.`)}
}

function render(){let yr=$('#year');yr.innerHTML=Array.from({length:9},(_,i)=>state.year-4+i).map(y=>`<option ${y===state.year?'selected':''}>${y}</option>`).join('');$('#main').innerHTML=({home:renderHome,activity:renderActivity,budget:renderBudget,wealth:renderWealth,invest:renderPortfolio,plan:renderPlan,reports:renderReports}[page])();document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('selected',b.dataset.page===page));}
