function persistAllocation(month,values){
 const keys=['Need','Want','Savings'];
 if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)||keys.some(k=>!Number.isFinite(values[k])||values[k]<0||values[k]>100)||Math.abs(keys.reduce((t,k)=>t+values[k],0)-100)>0.00001)throw Error('Needs, Wants and Savings must total 100%.');
 const prev=state.allocationTargets?.[month];state.allocationTargets??={};state.allocationTargets[month]={...values};
 try{safeStore.setItem(STORAGE,JSON.stringify(state));const copy=JSON.parse(safeStore.getItem(STORAGE)||'{}').allocationTargets?.[month];if(!copy||keys.some(k=>Math.abs(Number(copy[k])-values[k])>0.00001))throw Error('Saved values could not be verified.');}
 catch(err){if(prev)state.allocationTargets[month]=prev;else delete state.allocationTargets[month];throw err;}
 invalidateTransactionCache();focusMonth=Number(month.slice(5));state.year=Number(month.slice(0,4));syncClient?.changed();render();
 const confirm=$('#allocationConfirmation');if(confirm){confirm.textContent=`✓ Saved for ${month}: Needs ${values.Need}% · Wants ${values.Want}% · Savings ${values.Savings}%`;confirm.hidden=false;}
 return true;
}
